"""D1 sections use only saved complete/NA outcomes; no invented partial averages."""
import csv,json
from v3_revision import ROOT,RESULT,para,sub,table,eq

def augment_baselines(c):
    out=RESULT/'round2/baselines'
    if not (out/'summary.csv').exists():return
    rows=list(csv.DictReader((out/'summary.csv').open()));pairs=list(csv.DictReader((out/'paired-tests.csv').open()));total=json.loads((out/'summary.json').read_text())
    f=lambda x:'NA' if x in (None,'') else format(float(x),'.4g')
    def same(r,s,h,w,m):return (r['source'],int(r['horizon']),int(r['window']),r.get('method',r.get('left_method')))==(s,h,w,m)
    def pair(s,h,w,m,ref):return next(p for p in pairs if same(p,s,h,w,m) and p['right_method']==ref)
    short=[]
    for s,ws in [('fx_hourly',(720,2880)),('nyfed_weekly',(52,260))]:
      for h in (6,24):
       for w in ws:
        row=['FX' if s=='fx_hourly' else 'Treasury',str(h),str(w)]
        for m in ('FHS','PEAK_POT','QRF'):
          r=next(p for p in rows if same(p,s,h,w,m));p=pair(s,h,w,m,'frozen_F')
          row.append(f(p.get('relative_loss_percent'))+' / '+r['strict_breach_count'] if r['status']=='COMPLETE' else 'NA ('+str(r['completed_origin_count'])+' issued)')
        short.append(row)
    c['sections'][7]['blocks'].extend([
      sub('Post-result / exploratory mature conditional baselines'),
      table('Table 11. Fixed FHS, GARCH-scaled peak-headroom POT and true leaf-distribution QRF on all original cells. Each entry gives Δ loss% versus matched frozen F / strict breaches; negative Δ favors the new method. NA retains a failed or structurally ineligible complete-cell comparison; issued counts are not scored as partial successes. Full native losses, reasons and comparisons are in Appendix L.', ['Source','H','W','FHS: Δ% / hits','Peak POT: Δ% / hits','QRF: Δ% / hits'],short),
      para('These baselines use the original issue origins, mature-label windows and scheduled refits. FHS recursively simulates signed position paths from empirical GARCH-standardized innovations (Barone-Adesi et al., 1999). Peak POT fits GPD exceedances of GARCH-scaled mature peak headrooms; it is an adaptation of conditional EVT, not a literal McNeil–Frey (2000) return-innovation implementation. QRF uses the training-response distribution in matching tree leaves (Meinshausen, 2006), rather than quantiles of tree means. The configurations are fixed resource-bounded choices. Complete failures and adverse loss or breach changes remain visible.')])
    details=[]
    for r in rows:
      p=pair(r['source'],int(r['horizon']),int(r['window']),r['method'],'frozen_F');q=pair(r['source'],int(r['horizon']),int(r['window']),r['method'],'QR')
      details.append(['FX' if r['source']=='fx_hourly' else 'Treasury',r['horizon'],r['window'],r['method'],r['status'],f(r.get('mean_pinball')),r.get('strict_breach_count') or 'NA',f(p.get('relative_loss_percent')),f(q.get('relative_loss_percent'))])
    blocks=[
      para('Every addition in this appendix is post-result / exploratory. No D1 result replaces either original primary, its parameter selection, the original72-comparison Holm family or any archived result. The fixed protocol and code/version fingerprints precede the financial executions. The three new methods have '+str(total['complete_cells'])+' complete cells and '+str(total['NA_cells'])+' retained NA cells out of '+str(total['planned_cells'])+'. There is no omitted-date scoring or fallback report.'),
      sub('Filter and simulated-path FHS'),
      para('At refit κ, the W completed origins span i₀=κ−H−W+1 through κ−H. Fit a constant-mean Gaussian-QMLE GARCH(1,1) to increments in the same position envelope, containing W+H−1 increments. A training-only RMS conditions the fit numerically. A single optimization is allowed; failures remain NA. The coefficients and standardized residual pool are frozen between refits; newly observed increments update the variance state through issue t. In-sample historical filtered volatilities estimated at κ are not historical forecasts made at i. Finite fitted recursion and optimizer termination supply no independence, stationarity or coverage guarantee.'),
      eq('Δ<sub>j</sub>=μ<sub>G</sub>+ε<sub>j</sub>,   ε<sub>j</sub>=σ<sub>j</sub>z<sub>j</sub>,   σ<sub>j</sub><super>2</super>=ω<sub>G</sub>+α<sub>G</sub>ε<sub>j−1</sub><super>2</super>+β<sub>G</sub>σ<sub>j−1</sub><super>2</super>.',r'\Delta_j=\mu_G+\varepsilon_j,\qquad\varepsilon_j=\sigma_j z_j,\qquad\sigma_j^2=\omega_G+\alpha_G\varepsilon_{j-1}^2+\beta_G\sigma_{j-1}^2.'),
      para('The subscript G marks local GARCH coefficients, distinguishing them from the regression intercept and fixed-report preference ratio used elsewhere. The POT shape and scale below carry hats and refer to a separate tail fit.'),
      para('FHS draws2048 iid residual paths with replacement, using a seed bound to source, H, W and κ; draws are shared within that refit block. Each path recursively updates GARCH variance and signed increments from actual N<sub>t</sub>. Its simulated maximum includes h=0, and the empirical headroom quantile uses rank ⌈19(M+1)/20⌉. The fitted mean equation is constant; resampling retains the stored standardized residuals without further empirical recentering or rescaling, so their finite resampling distribution need not have exactly zero mean or unit variance. This is a same-target adaptation, rather than an exact replica of the original derivative-portfolio application.'),
      eq('P<sub>t,H</sub><super>(s)</super>=max<sub>0≤h≤H</sub>|N<sub>t</sub>+∑<sub>ℓ=1</sub><super>h</super>Δ<sub>ℓ</sub><super>(s)</super>|,   G<sub>t,H</sub><super>(s)</super>=P<sub>t,H</sub><super>(s)</super>−B<sub>t</sub>.',r'P_{t,H}^{(s)}=\max_{0\le h\le H}\left|N_t+\sum_{\ell=1}^{h}\Delta_{\ell}^{(s)}\right|,\qquad G_{t,H}^{(s)}=P_{t,H}^{(s)}-B_t.'),
      sub('Peak-headroom POT adaptation'),
      para('Normalize each mature headroom by the frozen filter’s one-step volatility at its historical starting origin. The threshold leaves ⌊0.1W⌋ potential upper observations; strict exceedances and ties determine the actual m. A minimum20 excesses, valid GPD support, positive scale and the declared shape regularity gate are required. Thus W52 is structurally ineligible. The single declared Nelder–Mead fit uses no alternate start, threshold or fallback. The quantile below uses the continuous exponential limit at zero shape.'),
      eq('R<sub>i</sub>=G<sub>i,H</sub>/σ̂<sub>i+1|κ</sub>,   q̂<sub>0.95</sub>=u+(β̂/ξ̂)[((m/W)/0.05)<super>ξ̂</super>−1],   C<sub>t</sub>=B<sub>t</sub>+σ̂<sub>t+1|κ</sub>max{0,q̂<sub>0.95</sub>}.',r'R_i=G_{i,H}/\hat\sigma_{i+1\mid\kappa},\quad\hat q_{.95}=u+\frac{\hat\beta}{\hat\xi}\left[\left(\frac{m/W}{.05}\right)^{\hat\xi}-1\right],\quad C_t=B_t+\hat\sigma_{t+1\mid\kappa}\max(0,\hat q_{.95}).'),
      para('McNeil and Frey (2000) fit tails of filtered one-step return innovations and simulate multi-period sums. The present headroom-tail scaling is not that original procedure. Dependence on the signed anchor relative to volatility, drift and the future variance path remains after a single-scale normalization; overlapping mature labels remain dependent. These are substantive approximation limits, not cured by successful GPD optimization.'),
      sub('Quantile-regression forest'),
      para('The forest uses the same33 causal predictors, training-only transforms and response scaling as QR. The fixed100-tree regression partitions have max_features11, minimum leaf5, split10, maximum depth10, bootstrap enabled and one worker. All original training rows receive within-leaf mass, averaged over trees; bootstrap chooses partitions but does not multiply these CDF masses. The left inverse at0.95 selects a positive-mass training response with no interpolation or F rank correction. This bounded fixed configuration is not claimed to optimize QRF or transfer the original consistency theorem to dependent fixed-window data.'),
      eq('w<sub>i</sub>(z)=(1/100)∑<sub>b=1</sub><super>100</super>1{z<sub>i</sub>∈L<sub>b</sub>(z)}/#{j:z<sub>j</sub>∈L<sub>b</sub>(z)},   F̂(y|z)=∑<sub>i</sub>w<sub>i</sub>(z)1{G<sub>i,H</sub>/a<sub>κ</sub>≤y}.',r'w_i(z)=\frac1{100}\sum_{b=1}^{100}\frac{\mathbf1\{z_i\in L_b(z)\}}{\#\{j:z_j\in L_b(z)\}},\qquad\hat F(y\mid z)=\sum_iw_i(z)\mathbf1\{G_{i,H}/a_\kappa\le y\}.'),
      table('Table L1. All24 planned method cells. Loss is native FX USD or Treasury USD millions. Failed complete cells have NA, regardless of earlier issued reports; no partial average substitutes for the full evaluation.', ['Source','H','W','Method','Status','Loss','Hits','Δ F %','Δ QR %'],details),
      table('Table L2. All48 planned paired comparisons. Tests are post-result working references; NA component tests remain NA. A separate48-slot Holm family reserves missing/degenerate slots as1 for adjustment only. This is distinct from claiming an observed valid p value of1. Negative Δ/t favors the new method; shared training and inspected outcomes limit interpretation.', ['Source','H','W','Method','Ref','Δloss %','DM t','DM p','HLN p','Holm p'],[['FX' if r['source']=='fx_hourly' else 'Treasury',r['horizon'],r['window'],r['left_method'],r['right_method'].removeprefix('frozen_'),f(r.get('relative_loss_percent')),f(r.get('dm_t')),f(r.get('dm_p')),f(r.get('hln_p')),f(r.get('holm_p'))] for r in pairs]),
      sub('Retained cell failures')]
    for r in rows:
      if r['status']!='COMPLETE':blocks.append(para((r['source']+' H'+r['horizon']+' W'+r['window']+' '+r['method']+': '+str(r.get('failure_type'))+' — '+str(r.get('failure_reason'))+'. Issued observations before failure: '+r['completed_origin_count']+'.').replace('<','&lt;').replace('>','&gt;')))
    counts=[]
    for m in ('FHS','PEAK_POT','QRF'):
        pp=[r for r in pairs if r['left_method']==m and r['right_method']=='frozen_F' and r['status']=='OK']
        counts.append(m+': '+str(sum(float(r['relative_loss_percent'])<0 for r in pp))+' lower-loss and '+str(sum(float(r['relative_loss_percent'])>0 for r in pp))+' higher-loss cells out of '+str(len(pp))+' complete comparisons')
    c['sections'][7]['blocks'].append(para('Against matched F, the complete-cell counts are '+('; '.join(counts))+'. These are descriptive counts across related histories and targets, not independent replications. The failed cells limit method coverage; they do not establish predictive inferiority.'))
    readback=json.loads((out/'independent-readback.json').read_text())
    fails=readback['failures'];boundary=[r for r in fails if r['kind']=='PERSISTENCE_GATE_WITH_OPTIMIZER_SUCCESS']
    blocks.extend([
      para('The '+str(len(boundary))+' short-history FX filter rejections have successful optimizer flags. Stored coefficients violate only the declared persistence tolerance after all other recorded admissibility conditions are verified. A fixed-coefficient readback invokes no optimizer and issues no new forecast; it reproduces the retained conditional-variance and standardized-residual hashes. No tolerance is relaxed and no rejected cell is rescored. These are numerical admissibility exclusions, not optimizer nonconvergence or evidence that FHS/POT predicts worse. The two short-history Treasury POT exclusions instead follow the minimum-tail-size rule.'),
      eq('α<sub>G</sub>+β<sub>G</sub>≤1+10<super>−10</super>.',r'\alpha_G+\beta_G\le1+10^{-10}.'),
      table('Table L3. Every retained NA classification. For boundary fits, δ is fitted persistence minus one and ε is excess over the declared numerical ceiling; optimizer flag0 denotes success. Strict-tail structural exclusions have no fitted persistence. No missing full-cell loss is imputed.', ['Source','H','W','Method','Issued','Class','δ','ε','Flag'],[['FX' if r['source']=='fx_hourly' else 'Treasury',str(r['horizon']),str(r['window']),r['method'],str(r['issued_before_failure']),'Boundary tolerance' if r['kind']=='PERSISTENCE_GATE_WITH_OPTIMIZER_SUCCESS' else 'Tail size',f(r.get('persistence_minus_one')),f(r.get('excess_over_declared_ceiling')),str(r.get('optimizer_convergence_flag','NA'))] for r in fails]),
      para('The separate48-slot Holm adjustment concerns only these working-reference comparisons. It does not control selection across every supplement or validate the component reference distributions. Remaining alternatives include canonical innovation-tail EVT, CAViaR and sequential conformal procedures. Neither these added baselines nor the aggregate panel supplies compatible unseen-dealer validation.')])
    c['sections'][9]['blocks'].append(para('Fixed FHS, peak-POT and leaf-distribution QRF add adverse outcomes and explicit numerical exclusions rather than a universal accuracy ranking. Compatible unseen-dealer evidence remains an open requirement.'))
    c['sections'].append(dict(title='Appendix L. Post-result / exploratory mature-baseline methods and complete outputs',blocks=blocks))
    for sec in c['sections']:
      if sec['title'].startswith('9.'):
       for b in sec['blocks']:
        if b['type']=='p' and 'strongest alternatives extend beyond' in b['html']:
          b['html']='Further alternatives include CAViaR, sequential conformal procedures, richer mean or volatility dynamics, and canonical innovation-tail conditional EVT. The fixed FHS, QRF and peak-POT additions in Appendix L extend the executed menu, with their failures and resource bounds retained. Same mature-label pools and update schedules improve procedural comparability while leaving different feature lookbacks, model assumptions and estimation rules. Compatible new dealer observations and decision-linked inputs remain necessary for broader portability.'
    if not any(r['id']=='mcneilfrey2000' for r in c['references']):
      c['references'].append(dict(id='mcneilfrey2000',html="McNeil, A.J., and Frey, R. (2000). Estimation of tail-related risk measures for heteroscedastic financial time series: an extreme value approach. <i>Journal of Empirical Finance</i>7(3–4),271–300. <a href='https://doi.org/10.1016/S0927-5398(00)00012-8'>DOI:10.1016/S0927-5398(00)00012-8</a>."))
